-- Server-only recovery challenges. Authentication codes and access tokens are
-- never stored; the destination code is a keyed digest generated by the server.
BEGIN;
CREATE TABLE public.contact_recovery_challenges (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  target text NOT NULL CHECK (target IN ('phone', 'email')),
  destination text NOT NULL,
  source text NOT NULL,
  code_digest text,
  attempts integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  consumed_at timestamptz
);
CREATE INDEX contact_recovery_user_created_idx ON public.contact_recovery_challenges(user_id, created_at DESC);
ALTER TABLE public.contact_recovery_challenges ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.contact_recovery_challenges FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.contact_recovery_challenges TO service_role;

-- Serialize creation per account and enforce a durable per-account rate limit.
CREATE OR REPLACE FUNCTION public.create_contact_recovery_challenge(
  p_id uuid, p_user_id uuid, p_target text, p_destination text, p_source text, p_digest text
) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_user_id::text, 0));
  DELETE FROM public.contact_recovery_challenges WHERE created_at < now() - interval '24 hours';
  IF (SELECT count(*) FROM public.contact_recovery_challenges WHERE user_id = p_user_id AND created_at > now() - interval '1 hour') >= 5 THEN RETURN false; END IF;
  UPDATE public.contact_recovery_challenges SET consumed_at = now() WHERE user_id = p_user_id AND consumed_at IS NULL;
  INSERT INTO public.contact_recovery_challenges(id,user_id,target,destination,source,code_digest,expires_at)
  VALUES (p_id,p_user_id,p_target,p_destination,p_source,p_digest,now()+interval '10 minutes');
  RETURN true;
END;
$$;

-- Atomically bound attempts and consume the challenge before an auth mutation.
CREATE OR REPLACE FUNCTION public.consume_contact_recovery_challenge(
  p_id uuid, p_user_id uuid, p_target text, p_digest text
) RETURNS TABLE(destination text, source text) LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE c public.contact_recovery_challenges%ROWTYPE;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  SELECT * INTO c FROM public.contact_recovery_challenges WHERE id=p_id AND user_id=p_user_id AND target=p_target FOR UPDATE;
  IF NOT FOUND OR c.consumed_at IS NOT NULL OR c.expires_at <= now() OR c.attempts >= 5 THEN RETURN; END IF;
  UPDATE public.contact_recovery_challenges SET attempts=attempts+1 WHERE id=c.id;
  IF c.target='email' AND (p_digest IS NULL OR c.code_digest IS DISTINCT FROM p_digest) THEN RETURN; END IF;
  UPDATE public.contact_recovery_challenges SET consumed_at=now() WHERE id=c.id;
  RETURN QUERY SELECT c.destination,c.source;
END;
$$;
REVOKE ALL ON FUNCTION public.create_contact_recovery_challenge(uuid,uuid,text,text,text,text) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.consume_contact_recovery_challenge(uuid,uuid,text,text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.create_contact_recovery_challenge(uuid,uuid,text,text,text,text) TO service_role;
GRANT EXECUTE ON FUNCTION public.consume_contact_recovery_challenge(uuid,uuid,text,text) TO service_role;
COMMIT;
